using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace Aesthetik.SchemaFix
{
    public class AesthetikSchemaFixInstallerV3 : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null)
                {
                    WriteLog("[AesthetikSchemaFixV3] No ProjectX connection string found, trying alternatives...");
                    foreach (ConnectionStringSettings s in ConfigurationManager.ConnectionStrings)
                    {
                        WriteLog("[AesthetikSchemaFixV3] Found connection: " + s.Name);
                    }
                    return;
                }
                string connStr = cs.ConnectionString;
                WriteLog("[AesthetikSchemaFixV3] Using System.Data.SqlClient with connection: " + cs.Name);

                using (var conn = new SqlConnection(connStr))
                {
                    conn.Open();
                    WriteLog("[AesthetikSchemaFixV3] Connection opened successfully");
                    string[] statements = new[]
                    {
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrComplianceHold') ALTER TABLE SOOrder ADD UsrComplianceHold bit NULL",
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('SOOrder') AND name = 'UsrComplianceHoldReason') ALTER TABLE SOOrder ADD UsrComplianceHoldReason nvarchar(500) NULL",
                        "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('BAccount') AND name = 'UsrDisablePayLink') ALTER TABLE BAccount ADD UsrDisablePayLink bit NULL"
                    };
                    foreach (string sql in statements)
                    {
                        using (var cmd = conn.CreateCommand())
                        {
                            cmd.CommandText = sql;
                            cmd.ExecuteNonQuery();
                        }
                        string col = sql.Substring(sql.IndexOf("name = '") + 8);
                        col = col.Substring(0, col.IndexOf("'"));
                        WriteLog("[AesthetikSchemaFixV3] OK: " + col);
                    }
                }
                WriteLog("[AesthetikSchemaFixV3] All columns created successfully");
            }
            catch (Exception ex)
            {
                WriteLog("[AesthetikSchemaFixV3] ERROR: " + ex.GetType().FullName + ": " + ex.Message);
                if (ex.InnerException != null)
                    WriteLog("[AesthetikSchemaFixV3] Inner: " + ex.InnerException.Message);
            }
        }
    }
}

using System;
using PX.Data;
using PX.Data.BQL;
using PX.Data.BQL.Fluent;
using PX.SM;

namespace StudioB.Inquiry
{
    /// <summary>
    /// Read-only inquiry graph that exposes PX.SM.AuditHistory via BQL.
    /// Accessible via SOAP screen-based API at /Soap/SB205530.asmx
    /// or via Contract-Based API if registered as an endpoint entity.
    /// </summary>
    public class StudioBAuditInquiry : PXGraph<StudioBAuditInquiry>
    {
        public PXSelect<
            AuditHistory,
            Where<AuditHistory.screenID, IsNotNull>,
            OrderBy<Desc<AuditHistory.changeDate>>
        > AuditRecords;
    }
}

using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace StudioB.Setup
{
    /// <summary>
    /// Self-contained GI creator: creates the StudioBAuditTrail Generic Inquiry
    /// from scratch via direct SQL, including GIDesign, GITable, GIResult rows,
    /// and OData flag. Survives CI/CD rollbacks (re-creates if missing).
    ///
    /// Approach: copies column structure from an existing GIResult row to avoid
    /// NOT NULL column guessing. Uses INSERT...SELECT with overrides.
    /// </summary>
    public class StudioBAuditGISetup : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            WriteLog("[AuditGISetup] Starting self-contained GI creation...");

            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null) { WriteLog("[AuditGISetup] No ProjectX connection string"); return; }

                using (var conn = new SqlConnection(cs.ConnectionString))
                {
                    conn.Open();

                    // Get CompanyID from an existing GI
                    int companyId = 0;
                    using (var cmd = new SqlCommand("SELECT TOP 1 CompanyID FROM GIDesign WHERE CompanyID > 0", conn))
                    {
                        var r = cmd.ExecuteScalar();
                        if (r != null) companyId = (int)r;
                    }
                    if (companyId == 0) { WriteLog("[AuditGISetup] No CompanyID found"); return; }
                    WriteLog("[AuditGISetup] CompanyID: " + companyId);

                    // Check if GI already exists
                    string designId = null;
                    using (var cmd = new SqlCommand(
                        "SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GIDesign WHERE Name = 'StudioBAuditTrail' AND CompanyID = @cid", conn))
                    {
                        cmd.Parameters.AddWithValue("@cid", companyId);
                        var r = cmd.ExecuteScalar();
                        if (r != null && r != DBNull.Value) designId = r.ToString();
                    }

                    if (designId == null)
                    {
                        // CREATE the GI — copy structure from any existing GIDesign row
                        designId = Guid.NewGuid().ToString();
                        WriteLog("[AuditGISetup] Creating GI with DesignID: " + designId);

                        // Get a template DesignID to copy column structure
                        string templateId = null;
                        using (var cmd = new SqlCommand(
                            "SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GIDesign WHERE CompanyID = @cid AND ExposeViaOData = 1", conn))
                        {
                            cmd.Parameters.AddWithValue("@cid", companyId);
                            var r = cmd.ExecuteScalar();
                            if (r != null && r != DBNull.Value) templateId = r.ToString();
                        }
                        if (templateId == null)
                        {
                            using (var cmd2 = new SqlCommand(
                                "SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GIDesign WHERE CompanyID = @cid", conn))
                            {
                                cmd2.Parameters.AddWithValue("@cid", companyId);
                                var r2 = cmd2.ExecuteScalar();
                                if (r2 != null && r2 != DBNull.Value) templateId = r2.ToString();
                            }
                        }
                        if (templateId == null) { WriteLog("[AuditGISetup] No template GI found"); return; }

                        // Copy the template row and override key fields
                        using (var cmd = conn.CreateCommand())
                        {
                            // Get column names dynamically (exclude identity/computed cols)
                            cmd.CommandText = @"
                                SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                                WHERE TABLE_NAME = 'GIDesign'
                                AND COLUMN_NAME NOT IN ('DeletedDatabaseRecord','Tstamp')
                                AND DATA_TYPE NOT IN ('timestamp')
                                ORDER BY ORDINAL_POSITION";
                            var cols = new System.Collections.Generic.List<string>();
                            using (var reader = cmd.ExecuteReader())
                            {
                                while (reader.Read()) cols.Add(reader.GetString(0));
                            }
                            WriteLog("[AuditGISetup] GIDesign has " + cols.Count + " columns");

                            // Build INSERT...SELECT with overrides
                            var selectParts = new System.Collections.Generic.List<string>();
                            foreach (var col in cols)
                            {
                                switch (col)
                                {
                                    case "DesignID": selectParts.Add("'" + designId + "'"); break;
                                    case "Name": selectParts.Add("'StudioBAuditTrail'"); break;
                                    case "ExposeViaOData": selectParts.Add("0"); break; // DISABLED until field names verified
                                    case "ScreenID": selectParts.Add("'GI000000'"); break;
                                    case "FilterColCount": selectParts.Add("3"); break;
                                    case "PageSize": selectParts.Add("200"); break;
                                    case "NoteID": selectParts.Add("NEWID()"); break;
                                    case "RowID": selectParts.Add("NEWID()"); break;
                                    case "CreatedDateTime": case "LastModifiedDateTime": selectParts.Add("GETUTCDATE()"); break;
                                    default: selectParts.Add("[" + col + "]"); break;
                                }
                            }

                            cmd.CommandText = "INSERT INTO GIDesign ([" + string.Join("],[", cols) + "]) SELECT " +
                                string.Join(",", selectParts) + " FROM GIDesign WHERE DesignID = @tid AND CompanyID = @cid";
                            cmd.Parameters.AddWithValue("@tid", templateId);
                            cmd.Parameters.AddWithValue("@cid", companyId);
                            cmd.ExecuteNonQuery();
                            WriteLog("[AuditGISetup] GIDesign row created");
                        }

                        // Create GITable (data source) row — same pattern
                        using (var cmd = conn.CreateCommand())
                        {
                            cmd.CommandText = @"
                                SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                                WHERE TABLE_NAME = 'GITable'
                                AND COLUMN_NAME NOT IN ('DeletedDatabaseRecord','Tstamp')
                                AND DATA_TYPE NOT IN ('timestamp')
                                ORDER BY ORDINAL_POSITION";
                            var cols = new System.Collections.Generic.List<string>();
                            using (var reader = cmd.ExecuteReader()) { while (reader.Read()) cols.Add(reader.GetString(0)); }

                            // Get a template GITable row
                            string templateTableId = null;
                            using (var cmd2 = new SqlCommand(
                                "SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GITable WHERE DesignID = @tid AND CompanyID = @cid", conn))
                            {
                                cmd2.Parameters.AddWithValue("@tid", templateId);
                                cmd2.Parameters.AddWithValue("@cid", companyId);
                                var r = cmd2.ExecuteScalar();
                                if (r != null && r != DBNull.Value) templateTableId = r.ToString();
                            }
                            if (templateTableId == null) { WriteLog("[AuditGISetup] No template GITable"); return; }

                            var selectParts = new System.Collections.Generic.List<string>();
                            foreach (var col in cols)
                            {
                                switch (col)
                                {
                                    case "DesignID": selectParts.Add("'" + designId + "'"); break;
                                    case "Name": selectParts.Add("'PX.SM.AuditHistory'"); break;
                                    case "Alias": selectParts.Add("'AuditHistory'"); break;
                                    case "NoteID": case "RowID": selectParts.Add("NEWID()"); break;
                                    case "CreatedDateTime": case "LastModifiedDateTime": selectParts.Add("GETUTCDATE()"); break;
                                    default: selectParts.Add("[" + col + "]"); break;
                                }
                            }

                            cmd.CommandText = "INSERT INTO GITable ([" + string.Join("],[", cols) + "]) SELECT TOP 1 " +
                                string.Join(",", selectParts) + " FROM GITable WHERE DesignID = @tid AND CompanyID = @cid";
                            cmd.Parameters.Clear();
                            cmd.Parameters.AddWithValue("@tid", templateId);
                            cmd.Parameters.AddWithValue("@cid", companyId);
                            cmd.ExecuteNonQuery();
                            WriteLog("[AuditGISetup] GITable row created (PX.SM.AuditHistory)");
                        }
                    }
                    else
                    {
                        WriteLog("[AuditGISetup] GI already exists: " + designId);
                        // DISABLE OData until field names are verified
                        using (var cmd = new SqlCommand("UPDATE GIDesign SET ExposeViaOData = 0 WHERE DesignID = @did AND CompanyID = @cid", conn))
                        {
                            cmd.Parameters.AddWithValue("@did", designId);
                            cmd.Parameters.AddWithValue("@cid", companyId);
                            cmd.ExecuteNonQuery();
                        }
                    }

                    // Delete existing result rows (clean slate)
                    using (var cmd = new SqlCommand("DELETE FROM GIResult WHERE DesignID = @did AND CompanyID = @cid", conn))
                    {
                        cmd.Parameters.AddWithValue("@did", designId);
                        cmd.Parameters.AddWithValue("@cid", companyId);
                        int deleted = cmd.ExecuteNonQuery();
                        WriteLog("[AuditGISetup] Cleared " + deleted + " result rows");
                    }

                    // Insert result columns using INSERT...SELECT from template
                    string[] fields = { "ScreenID", "Operation", "ChangeDate", "UserName", "TableName", "BatchID", "ChangeID", "CombinedKey", "ModifiedFields" };

                    // Get GIResult column names
                    var resultCols = new System.Collections.Generic.List<string>();
                    using (var cmd = new SqlCommand(@"
                        SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                        WHERE TABLE_NAME = 'GIResult' AND COLUMN_NAME NOT IN ('DeletedDatabaseRecord','Tstamp')
                        AND DATA_TYPE NOT IN ('timestamp') ORDER BY ORDINAL_POSITION", conn))
                    {
                        using (var reader = cmd.ExecuteReader()) { while (reader.Read()) resultCols.Add(reader.GetString(0)); }
                    }
                    WriteLog("[AuditGISetup] GIResult has " + resultCols.Count + " columns");

                    // Find a template GIResult row from any GI
                    string tplDesign = null;
                    using (var cmd = new SqlCommand("SELECT TOP 1 CONVERT(NVARCHAR(36), DesignID) FROM GIResult WHERE CompanyID = @cid", conn))
                    {
                        cmd.Parameters.AddWithValue("@cid", companyId);
                        var r = cmd.ExecuteScalar();
                        if (r != null && r != DBNull.Value) tplDesign = r.ToString();
                    }
                    if (tplDesign == null) { WriteLog("[AuditGISetup] No template GIResult rows exist"); return; }

                    for (int i = 0; i < fields.Length; i++)
                    {
                        var selectParts = new System.Collections.Generic.List<string>();
                        foreach (var col in resultCols)
                        {
                            switch (col)
                            {
                                case "DesignID": selectParts.Add("'" + designId + "'"); break;
                                case "LineNbr": selectParts.Add((i + 1).ToString()); break;
                                case "IsActive": selectParts.Add("1"); break;
                                case "ObjectName": selectParts.Add("'AuditHistory'"); break;
                                case "Field": selectParts.Add("'" + fields[i] + "'"); break;
                                case "SchemaField": selectParts.Add("NULL"); break;
                                case "SortOrder": selectParts.Add((i + 1).ToString()); break;
                                case "IsVisible": selectParts.Add("1"); break;
                                case "Width": selectParts.Add("120"); break;
                                case "Caption": selectParts.Add("'" + fields[i] + "'"); break;
                                case "QuickFilter": case "FastFilter": case "DefaultNav": selectParts.Add("0"); break;
                                case "NoteID": case "RowID": selectParts.Add("NEWID()"); break;
                                case "CreatedDateTime": case "LastModifiedDateTime": selectParts.Add("GETUTCDATE()"); break;
                                default: selectParts.Add("[" + col + "]"); break;
                            }
                        }

                        using (var cmd = new SqlCommand(
                            "INSERT INTO GIResult ([" + string.Join("],[", resultCols) + "]) SELECT TOP 1 " +
                            string.Join(",", selectParts) + " FROM GIResult WHERE DesignID = @tid AND CompanyID = @cid", conn))
                        {
                            cmd.Parameters.AddWithValue("@tid", tplDesign);
                            cmd.Parameters.AddWithValue("@cid", companyId);
                            cmd.ExecuteNonQuery();
                        }
                        WriteLog("[AuditGISetup] Added: " + fields[i]);
                    }

                    WriteLog("[AuditGISetup] Complete — " + fields.Length + " columns, OData enabled");
                }
            }
            catch (Exception ex)
            {
                WriteLog("[AuditGISetup] ERROR: " + ex.GetType().FullName + ": " + ex.Message);
                if (ex.InnerException != null)
                    WriteLog("[AuditGISetup] Inner: " + ex.InnerException.Message);
            }
        }
    }
}
